class GMap {
  constructor(dom) {
    this.dom = dom;
    this.polylines = [];
  }

  async init() {
    const { Map } = await google.maps.importLibrary("maps");

    let tmpZoomLvl = window.innerWidth >= 768 ? 13 : 12;

    // console.log(tmpZoomLvl);
    this.map = new Map(this.dom, {
      center: { lat: 22.370852, lng: 114.321159 },
      zoom: tmpZoomLvl,
      clickableIcons: false,
      mapId: "d3d686afb8f6925b",
      scrollwheel: false,
      mapTypeControl: false,
      streetViewControl: false,
    });
  }

  async initMarkers(mapData) {
    this.data = mapData;
    this.map.addListener("click", () => {
      this.closeAllMarkers();
    });

    const { AdvancedMarkerElement } = await google.maps.importLibrary("marker");
    for (let d of this.data) {
      let markerContent;
      if (d.permalink == null || d.permalink == "") {
        markerContent = spotDivFactory(d);
      } else {
        markerContent = popUpDivFactory(d);
      }

      const marker = new AdvancedMarkerElement({
        map: this.map,
        position: { lat: d.lat, lng: d.lng },
        title: d.title,
        content: markerContent,
      });
      d.marker = marker;
      d.marker.workId = d.id;

      if (d.permalink !== null && d.permalink !== "") {
        marker.addListener("click", () => {
          if (marker.content.classList.contains("expand")) {
            const targetHref = marker.content
              .querySelector("a")
              .getAttribute("href");
            window.location.href = targetHref;
          } else {
            this.panToWork(marker.workId);
          }
        });
      }
    }
  }

  initPaths(pathData) {
    for (let pd of pathData) {
      const polyline = new google.maps.Polyline({
        path: JSON.parse(pd.json),
        strokeColor: pd.color,
        strokeOpacity: 1.0,
        strokeWeight: 2,
      });
      polyline.setMap(this.map);
      polyline.id = pd.id;
      polyline.zoomlvl = Number(pd.zoomlvl);
      polyline.lat = pd.lat;
      polyline.lng = pd.lng;
      if (pd.items) {
        polyline.mapItems = pd.items.split(",");
      } else {
        polyline.mapItems = [];
      }
      this.polylines.push(polyline);
    }
  }

  showPath(pathID, showNum = false) {
    for (let path of this.polylines) {
      if (path.id == pathID) {
        path.setVisible(true);
        if(path.zoomlvl && path.lat && path.lng){
          let tmpCenter = new google.maps.LatLng(path.lat, path.lng);
          this.map.setCenter(tmpCenter);
          this.map.setZoom(path.zoomlvl);
        }
        for (let d of this.data) {
          for (let [index, item] of path.mapItems.entries()) {
            if (d.marker.workId == item) {
              const indicatorDOM = d.marker.content.querySelector(".indicator");
              if (showNum == true) {
                indicatorDOM.textContent = index+1;
              } else {
                indicatorDOM.textContent = "";
              }
              d.marker.content.classList.remove("d-none");
            }
          }
        }
      }
    }
  }

  hidePath(pathID) {
    for (let path of this.polylines) {
      if (path.id == pathID) {
        path.setVisible(false);
        for (let d of this.data) {
          if (path.mapItems.includes(d.marker.workId)) {
            d.marker.content.classList.add("d-none");
          }
        }
      }
    }
  }

  showAllPaths() {
    for (let path of this.polylines) {
      path.setVisible(true);
    }
    for (let d of this.data) {
      d.marker.content.classList.remove("d-none");
      const indicatorDOM = d.marker.content.querySelector(".indicator");
      indicatorDOM.textContent = "";
    }
  }

  hideAllPaths() {
    for (let path of this.polylines) {
      path.setVisible(false);
    }
    for (let d of this.data) {
      d.marker.content.classList.add("d-none");
    }
  }

  async initDrawingManager() {
    this.drawnLines = [];
    const { DrawingManager } = await google.maps.importLibrary("drawing");
    this.drawingManager = new DrawingManager({
      drawingMode: google.maps.drawing.OverlayType.POLYLINE,
      drawingControl: true,
      drawingControlOptions: {
        position: google.maps.ControlPosition.TOP_CENTER,
        drawingModes: [google.maps.drawing.OverlayType.POLYLINE],
      },
    });
    this.drawingManager.setMap(this.map);

    google.maps.event.addListener(
      this.drawingManager,
      "polylinecomplete",
      (line) => {
        let pathArray = line.getPath().getArray();
        let output = `[`;
        for (let [index, vertex] of pathArray.entries()) {
          // console.log(vertex.lat(),vertex.lng());
          output += `{"lat":${vertex.lat()},"lng":${vertex.lng()}}`;
          if (index != pathArray.length - 1) {
            output += ",";
          }
        }
        output += `]`;

        const textArea = document.querySelector("#path-json");
        textArea.value = output;

        this.drawnLines.push(line);
      }
    );
  }

  initDebugTool() {
    const debugDOM = document.querySelector("#map-debugger");
    debugDOM.classList.remove("d-none");

    const copyBtn = document.querySelector("#btn-debug-copy");
    copyBtn.addEventListener("click", () => {
      const textArea = document.querySelector("#path-json");
      const text = textArea.value;
      navigator.clipboard.writeText(text).then(
        () => {
          // textArea.value = "";
          copyBtn.innerHTML = "Copied!";
          copyBtn.classList.remove("btn-primary");
          copyBtn.classList.add("btn-secondary");
          setTimeout(() => {
            copyBtn.innerHTML = "Copy";
            copyBtn.classList.remove("btn-secondary");
            copyBtn.classList.add("btn-primary");
          }, 1000);
          console.log("Async: Copying to clipboard was successful!");
        },
        (err) => {
          console.error("Async: Could not copy text: ", err);
        }
      );
    });

    const clearBtn = document.querySelector("#btn-debug-clear");
    clearBtn.addEventListener("click", () => {
      const textArea = document.querySelector("#path-json");
      textArea.value = "";

      for (let line of this.drawnLines) {
        line.setMap(null);
      }
      this.drawnLines = [];
    });
  }

  closeAllMarkers() {
    for (let d of this.data) {
      d.marker.content.classList.remove("expand");
      d.marker.zIndex = null;
    }
  }

  panToWork(id) {
    for (let d of this.data) {
      if (d.id == id) {
        this.map.panTo({ lat: d.lat, lng: d.lng });
        this.map.panBy(0, -100);
        this.closeAllMarkers();
        d.marker.content.classList.add("expand");
        d.marker.zIndex = 1;
      }
    }
  }
}

function spotDivFactory(data) {
  const wrapper = document.createElement("div");
  wrapper.classList.add("marker-wrapper");

  const indicator = document.createElement("div");
  indicator.classList.add("indicator");
  indicator.classList.add("spot");
  indicator.classList.add(`island-${data.islandID}`);

  wrapper.appendChild(indicator);

  return wrapper;
}

function popUpDivFactory(data) {
  const wrapper = document.createElement("div");
  wrapper.classList.add("marker-wrapper");

  const indicator = document.createElement("div");
  indicator.classList.add("indicator");
  indicator.classList.add(`island-${data.islandID}`);

  const popupDiv = document.createElement("div");
  popupDiv.classList.add("mapPopup");
  popupDiv.classList.add(`island-${data.islandID}`);

  const popupImg = document.createElement("img");
  popupImg.setAttribute("src", data.thumbnail);
  popupImg.setAttribute("alt", data.title);

  const popupTitle = document.createElement("h4");
  popupTitle.innerHTML = data.title;
  // popupTitle.textContent = data.title;

  popupDiv.appendChild(popupImg);
  popupDiv.appendChild(popupTitle);

  const aTag = document.createElement("a");
  aTag.setAttribute("href", data.permalink);
  aTag.appendChild(popupDiv);

  wrapper.appendChild(aTag);
  wrapper.appendChild(indicator);

  return wrapper;
}


