function islandIcon(dom) {
  const island = dom.getAttribute("data-island");
  const root = dom.getAttribute("data-root");
  const path = `${rootURL}assets/images/icon-${island}`;
  const icons = document.querySelectorAll("[js-island_icon]");

  if (
    dom == document.querySelector("#page-work-detail") ||
    dom == document.querySelector("#page-attraction-detail")
  ) {
    for (let icon of icons) {
      icon.setAttribute("src", `${path}.svg`);
    }
  } else if (dom == document.querySelector("#page-island-detail")) {
    // console.log("island-detail");
    let color;
    if (island == "yyt") {
      color = "sea";
    } else if (island == "sharp") {
      color = "navy";
    } else if (island == "ksv") {
      color = "green";
    } else if (island == "high") {
      color = "pink";
    } else if (island == "sk") {
      color = "pond";
    }
    for (let icon of icons) {
      icon.setAttribute("src", `${path}-${color}.svg`);
    }
  }
}


