    await this.gmap.initMarkers(this.mapData);
    this.gmap.initPaths(this.pathData);

    const anchorBtns = this.dom.querySelectorAll(".anchor-btn");
    for (let btn of anchorBtns) {
      btn.addEventListener("click", () => {
        const id = btn.getAttribute("data-id");
        this.gmap.panToWork(id);
        this.listingBtn.classList.remove("close");
        this.dom.classList.remove("list-open");
      });
    }
